/**
 * PostV2: the one post format shared by community posts (api-videos, Studio, the videos site), the
 * CMS (scholar post references, staff posts) and www (wiki AUN-SCHOLAR-SITES §6.3, decision SS5).
 *
 * A community post's JSON (R2 `community-posts`, `posts/{channelId}/{postId}.json`) is the source of
 * truth for every scholar post. This file holds what all three repos must agree on: the kinds, the
 * limits, the shape of the kind-specific fields, the validator for the fields Studio writes, and the
 * summary the CMS caches for www's lists and the home timeline.
 *
 * CANONICAL COPY. AlUmmahNowCMS and AlUmmahNowUI vendor this file byte for byte at a pinned commit
 * (`npm run sync:posts`, checked by `npm run check:posts`). So it must stay self-contained:
 *   - no imports;
 *   - erasable TypeScript only (no enums, namespaces or parameter properties), so Node's
 *     --experimental-strip-types and any bundler can run it as is.
 * Changes are additive: a new optional field or kind, never a rename. Bump POST_SCHEMA_REVISION when
 * the summary's shape changes, so the CMS refreshes cached summaries.
 */

export const POST_SCHEMA_VERSION = 2 as const;
/** Bumped when postSummary's output changes shape or content (the CMS re-summarises older refs). */
export const POST_SCHEMA_REVISION = 1 as const;

/** Every post kind, everywhere. `gif` is kept and `link` added (SS14, the spec's recommendation). */
export const POST_KINDS = ['text', 'image', 'poll', 'quiz', 'video', 'gif', 'link', 'article', 'cards'] as const;
export type PostKind = (typeof POST_KINDS)[number];
export const POST_LOCALES = ['en', 'ar'] as const;
export type PostLocale = (typeof POST_LOCALES)[number];
export const SLIDE_POSITIONS = ['top', 'middle', 'bottom'] as const;
export type SlidePosition = (typeof SLIDE_POSITIONS)[number];

export const POST_LIMITS = {
  text: 5000,
  title: 200,
  excerpt: 300,
  /** An article's markdown body. */
  articleBody: 100_000,
  slides: 40,
  /** How many slides a summary carries (lists and the timeline show a card post whole up to this). */
  summarySlides: 10,
  slideHeading: 140,
  slideBody: 400,
  alt: 300,
  images: 10,
  linkTitle: 200,
  linkDescription: 300,
  url: 2048,
  slug: 120,
  translationKey: 64,
} as const;

/** An image anywhere in a post: a cover, a card, a link preview. `alt` is required where it carries meaning (cards). */
export interface PostMedia {
  url: string;
  alt: string | null;
  width: number | null;
  height: number | null;
}

/** One card of a `cards` post: an image with real overlay text (never burned into the image). */
export interface PostSlide {
  id: string;
  image: PostMedia;
  heading: string | null;
  body: string | null;
  position: SlidePosition;
}

/** An `article` post. `url` is its www address, filled in once www has a reference for it. */
export interface PostArticle {
  title: string;
  excerpt: string | null;
  /** Markdown. HTML is never rendered. Absent on the link-only mirrors written before PostV2. */
  body?: string;
  cover?: PostMedia | null;
  /** Legacy (link-only mirrors): the cover's URL. Kept in step with `cover`. */
  coverUrl: string | null;
  url?: string;
  locale: PostLocale;
  /** The CMS's key for an article it wrote (`cms-<id>`), for the mirrors and the conversion. */
  externalId?: string;
}

/** A `link` post: an outside page with an optional preview. */
export interface PostLink {
  url: string;
  title: string | null;
  description: string | null;
  image: PostMedia | null;
}

/** Where www shows the post (written back by the reference sync). */
export interface PostWww {
  url: string;
  slug: string;
  locale: PostLocale;
}

/**
 * The PostV2 fields of a community post, on top of the community fields (id, channelId, type,
 * content, images, videoId, gif, poll, quiz, counters, status, visibility…). All optional on the
 * wire: posts written before PostV2 have none of them and still read correctly.
 */
export interface PostV2Fields {
  schemaVersion?: typeof POST_SCHEMA_VERSION;
  /** The post's language. Older posts: guessed from their text (postLocale). */
  locale?: PostLocale;
  /** Posts in two languages that are translations of each other share a key (www `alternates`). */
  translationKey?: string;
  /** A wanted www slug (articles, cards). www keeps the slug it first gave the post. */
  slug?: string;
  /** Cards (and optionally link) posts: the title. Articles keep theirs in `article.title`. */
  title?: string;
  article?: PostArticle;
  slides?: PostSlide[];
  link?: PostLink;
  www?: PostWww;
}

/** The loose shape the helpers read: any community post JSON. */
export interface PostLike extends PostV2Fields {
  id?: string;
  channelId?: string;
  type?: string;
  content?: string;
  images?: { url?: string; width?: number; height?: number; caption?: string }[];
  videoId?: string;
  gif?: { url?: string; width?: number; height?: number };
  poll?: { question?: string; options?: { id?: string; text?: string }[]; multipleChoice?: boolean; votingEndsAt?: string };
  quiz?: { question?: string; options?: { id?: string; text?: string }[] };
  status?: string;
  visibility?: string;
  scheduledAt?: string;
  createdAt?: string;
  updatedAt?: string;
  likes?: number;
  comments?: number;
  commentsEnabled?: boolean;
}

/* ── Validation of the fields Studio writes ───────────────────────────────────────────────────── */

export interface PostFieldError {
  ok: false;
  /** Stable code: the API answers with it and Studio shows its own message. */
  error: 'bad_kind' | 'required' | 'too_long' | 'too_many' | 'bad_url' | 'bad_media' | 'alt_required' | 'bad_value';
  field: string;
}
export type PostFieldsResult = { ok: true; value: PostV2Fields } | PostFieldError;

export interface PostValidateOptions {
  /** Hosts images may come from (covers, cards, link previews). Default: any https host. */
  mediaHost?: (host: string) => boolean;
}

const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g;
const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

/** Trimmed text without control characters (newlines kept when `multiline`), or '' for a non-string. */
export function cleanText(v: unknown, multiline = false): string {
  if (typeof v !== 'string') return '';
  const s = v.replace(CONTROL, '');
  return (multiline ? s.replace(/\r\n?/g, '\n') : s.replace(/[\r\n\t]+/g, ' ')).trim();
}

function httpsUrl(v: unknown, allowHttp = false): string | null {
  if (typeof v !== 'string' || v.length > POST_LIMITS.url) return null;
  try {
    const u = new URL(v);
    if (u.protocol !== 'https:' && !(allowHttp && u.protocol === 'http:')) return null;
    if (u.username || u.password) return null;
    return u.toString();
  } catch {
    return null;
  }
}

type Fail = (error: PostFieldError['error'], field: string) => never;
class FieldFail {
  constructor(r: PostFieldError) {
    this.r = r;
  }
  r: PostFieldError;
}
const fail: Fail = (error, field) => {
  throw new FieldFail({ ok: false, error, field });
};

function text(v: unknown, max: number, field: string, required: boolean, multiline = false): string {
  const s = cleanText(v, multiline);
  if (!s && required) fail('required', field);
  if (s.length > max) fail('too_long', field);
  return s;
}

function dim(v: unknown): number | null {
  return typeof v === 'number' && Number.isInteger(v) && v > 0 && v < 100_000 ? v : null;
}

function media(v: unknown, field: string, opts: PostValidateOptions, altRequired: boolean): PostMedia {
  if (!isObj(v)) return fail('bad_media', field);
  const url = httpsUrl(v.url);
  if (!url) return fail('bad_media', `${field}.url`);
  if (opts.mediaHost && !opts.mediaHost(new URL(url).hostname)) fail('bad_media', `${field}.url`);
  const alt = text(v.alt, POST_LIMITS.alt, `${field}.alt`, false);
  if (altRequired && !alt) fail('alt_required', `${field}.alt`);
  return { url, alt: alt || null, width: dim(v.width), height: dim(v.height) };
}

/** www-style slug: lowercase ASCII words joined by "-", or '' when nothing is left (e.g. Arabic only). */
export function slugify(v: unknown, max: number = POST_LIMITS.slug): string {
  if (typeof v !== 'string') return '';
  const words = v
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
  // Joined by hand (no trimming regex: linear on any input)
  let out = '';
  for (const w of words) {
    const next = out ? `${out}-${w}` : w;
    if (next.length > max) {
      if (!out) out = w.slice(0, max);
      break;
    }
    out = next;
  }
  return out;
}

const SLUG = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const KEY = /^[A-Za-z0-9_-]{1,64}$/;
const SLIDE_ID = /^[A-Za-z0-9_-]{1,40}$/;

export const isPostKind = (v: unknown): v is PostKind => typeof v === 'string' && (POST_KINDS as readonly string[]).includes(v);
export const isPostLocale = (v: unknown): v is PostLocale => v === 'en' || v === 'ar';

/**
 * Checks and normalises the PostV2 fields of a create or edit request for `kind`: the language,
 * translation key and slug for every kind, plus the article, cards or link content. The community
 * fields of the older kinds (text, images, poll, quiz, video, gif) are checked by api-videos as
 * before. Pure; never throws.
 */
export function parsePostFields(kind: unknown, raw: unknown, opts: PostValidateOptions = {}): PostFieldsResult {
  try {
    if (!isPostKind(kind)) return fail('bad_kind', 'type');
    const b = isObj(raw) ? raw : {};
    const out: PostV2Fields = { schemaVersion: POST_SCHEMA_VERSION };
    if (b.locale !== undefined && b.locale !== null) {
      if (!isPostLocale(b.locale)) fail('bad_value', 'locale');
      out.locale = b.locale as PostLocale;
    }
    if (b.translationKey !== undefined && b.translationKey !== null && b.translationKey !== '') {
      if (typeof b.translationKey !== 'string' || !KEY.test(b.translationKey)) fail('bad_value', 'translationKey');
      out.translationKey = b.translationKey as string;
    }
    if (b.slug !== undefined && b.slug !== null && b.slug !== '') {
      const slug = slugify(b.slug);
      if (!slug || !SLUG.test(slug)) fail('bad_value', 'slug');
      out.slug = slug;
    }
    if (kind === 'article') {
      const a = isObj(b.article) ? b.article : {};
      const cover = a.cover === undefined || a.cover === null ? null : media(a.cover, 'article.cover', opts, false);
      out.article = {
        title: text(a.title, POST_LIMITS.title, 'article.title', true),
        excerpt: text(a.excerpt, POST_LIMITS.excerpt, 'article.excerpt', false, true) || null,
        body: text(a.body, POST_LIMITS.articleBody, 'article.body', true, true),
        cover,
        coverUrl: cover ? cover.url : null,
        locale: out.locale ?? guessLocale(`${cleanText(a.title)} ${cleanText(a.body, true).slice(0, 400)}`),
      };
      out.locale = out.article.locale;
    } else if (kind === 'cards') {
      out.title = text(b.title, POST_LIMITS.title, 'title', true);
      if (!Array.isArray(b.slides) || b.slides.length === 0) fail('required', 'slides');
      const list = b.slides as unknown[];
      if (list.length > POST_LIMITS.slides) fail('too_many', 'slides');
      const seen = new Set<string>();
      out.slides = list.map((s, i) => {
        const f = `slides.${i}`;
        if (!isObj(s)) return fail('bad_value', f);
        const id = typeof s.id === 'string' && SLIDE_ID.test(s.id) && !seen.has(s.id) ? s.id : `s${i + 1}`;
        seen.add(id);
        const position = (SLIDE_POSITIONS as readonly unknown[]).includes(s.position) ? (s.position as SlidePosition) : 'bottom';
        return {
          id,
          image: media(s.image, `${f}.image`, opts, true),
          heading: text(s.heading, POST_LIMITS.slideHeading, `${f}.heading`, false) || null,
          body: text(s.body, POST_LIMITS.slideBody, `${f}.body`, false, true) || null,
          position,
        };
      });
    } else if (kind === 'link') {
      const l = isObj(b.link) ? b.link : {};
      const url = httpsUrl(l.url, true);
      if (!url) fail(l.url ? 'bad_url' : 'required', 'link.url');
      out.link = {
        url: url as string,
        title: text(l.title, POST_LIMITS.linkTitle, 'link.title', false) || null,
        description: text(l.description, POST_LIMITS.linkDescription, 'link.description', false, true) || null,
        image: l.image === undefined || l.image === null ? null : media(l.image, 'link.image', opts, false),
      };
      if (b.title !== undefined && b.title !== null && b.title !== '') out.title = text(b.title, POST_LIMITS.title, 'title', false);
    }
    return { ok: true, value: out };
  } catch (e) {
    if (e instanceof FieldFail) return e.r;
    throw e;
  }
}

/* ── Reading any post (older ones included) ───────────────────────────────────────────────────── */

const ARABIC = /[\u0600-\u06ff\u0750-\u077f\ufb50-\ufdff\ufe70-\ufeff]/g;
const LATIN = /[A-Za-z]/g;

/** 'ar' when Arabic letters outnumber Latin ones, else 'en'. */
export function guessLocale(s: string): PostLocale {
  const ar = (s.match(ARABIC) ?? []).length;
  const en = (s.match(LATIN) ?? []).length;
  return ar > en ? 'ar' : 'en';
}

/** Drops HTML tags in one pass (no backtracking regex). */
function stripTags(s: string): string {
  let out = '';
  let inTag = false;
  for (const ch of s) {
    if (ch === '<') inTag = true;
    else if (ch === '>' && inTag) {
      inTag = false;
      out += ' ';
    } else if (!inTag) out += ch;
  }
  return out;
}

/** Markdown (or the sanitised HTML of a text post) as plain text, for excerpts and titles. */
export function plainText(s: unknown): string {
  if (typeof s !== 'string') return '';
  return stripTags(s)
    .replace(/!\[[^\]\n]*\]\([^)\n]*\)/g, ' ')
    .replace(/\[([^\]\n]*)\]\([^)\n]*\)/g, '$1')
    .replace(/^[ \t]{0,3}(?:#{1,6}|>|[-*+]|\d{1,9}\.)[ \t]/gm, '')
    .replace(/[*_`~]/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    // &amp; last, so "&amp;lt;" stays "&lt;" (never unescaped twice)
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

const cut = (s: string, max: number) => {
  if (s.length <= max) return s;
  const head = s.slice(0, max - 1);
  const space = head.lastIndexOf(' ');
  return `${(space > max / 2 ? head.slice(0, space) : head).trimEnd()}\u2026`;
};

export function postKind(p: PostLike): PostKind {
  return isPostKind(p.type) ? p.type : 'text';
}

/** The post's language: its own, the article's, else guessed from its text. */
export function postLocale(p: PostLike): PostLocale {
  if (isPostLocale(p.locale)) return p.locale;
  if (p.article && isPostLocale(p.article.locale)) return p.article.locale;
  return guessLocale([p.title, p.content, p.poll?.question, p.quiz?.question, p.link?.title].filter(Boolean).join(' '));
}

/** A title for lists and www (never empty when the post has any text; '' otherwise). */
export function postTitle(p: PostLike): string {
  const candidates = [p.article?.title, p.title, p.poll?.question, p.quiz?.question, p.link?.title, firstLine(p.content), p.images?.[0]?.caption, p.link?.url];
  for (const c of candidates) {
    const s = plainText(c);
    if (s) return cut(s, 120);
  }
  return '';
}

function firstLine(s: unknown): string {
  if (typeof s !== 'string') return '';
  const plain = s.replace(/<br\s*\/?>|<\/p>/gi, '\n');
  return plain.split('\n').map((l) => plainText(l)).find(Boolean) ?? '';
}

export function postExcerpt(p: PostLike): string | null {
  const s = p.article ? plainText(p.article.excerpt) || plainText(p.article.body) : plainText(p.content) || plainText(p.link?.description) || plainText(p.slides?.[0]?.body);
  return s ? cut(s, POST_LIMITS.excerpt) : null;
}

const asMedia = (url: unknown, alt: unknown = null, w: unknown = null, h: unknown = null): PostMedia | null => {
  const u = httpsUrl(url);
  return u ? { url: u, alt: typeof alt === 'string' && alt ? alt : null, width: dim(w), height: dim(h) } : null;
};

/** The image that stands for the post in lists, or null. */
export function postCover(p: PostLike): PostMedia | null {
  if (p.article?.cover) return asMedia(p.article.cover.url, p.article.cover.alt, p.article.cover.width, p.article.cover.height);
  if (p.article?.coverUrl) return asMedia(p.article.coverUrl);
  const s = p.slides?.[0]?.image;
  if (s) return asMedia(s.url, s.alt, s.width, s.height);
  const i = p.images?.[0];
  if (i) return asMedia(i.url, i.caption, i.width, i.height);
  if (p.link?.image) return asMedia(p.link.image.url, p.link.image.alt, p.link.image.width, p.link.image.height);
  if (p.gif) return asMedia(p.gif.url, null, p.gif.width, p.gif.height);
  return null;
}

/**
 * What the CMS caches per scholar post (posts.summary_json) for www's lists, the home timeline and
 * search: enough to show any kind in a list without reading the post. Engagement counts are not in
 * it (they change all the time; the post page reads them live).
 */
export interface PostSummaryV2 {
  v: typeof POST_SCHEMA_REVISION;
  kind: PostKind;
  locale: PostLocale;
  title: string;
  excerpt: string | null;
  cover: PostMedia | null;
  /** Cards: the first POST_LIMITS.summarySlides cards; slide_count counts them all. */
  slides: PostSlide[];
  slide_count: number;
  /** Image posts: up to 4 images (alt from the caption). */
  images: PostMedia[];
  image_count: number;
  video_id: string | null;
  link: PostLink | null;
  poll: { question: string; options: { id: string; text: string }[] } | null;
  quiz: { question: string; options: { id: string; text: string }[] } | null;
  gif: PostMedia | null;
  /** Text posts: the text as plain text (≤ 1000 characters). */
  text: string | null;
}

const opts = (o: { id?: string; text?: string }[] | undefined) =>
  (o ?? []).slice(0, 10).map((x, i) => ({ id: typeof x.id === 'string' ? x.id : `option-${i}`, text: plainText(x.text).slice(0, 120) }));

export function postSummary(p: PostLike): PostSummaryV2 {
  const kind = postKind(p);
  const slides = (p.slides ?? []).filter((s) => s && s.image && httpsUrl(s.image.url));
  const images = (p.images ?? []).map((i) => asMedia(i.url, i.caption, i.width, i.height)).filter((m): m is PostMedia => m !== null);
  const textBody = kind === 'text' || kind === 'image' || kind === 'video' || kind === 'gif' ? plainText(p.content) : '';
  return {
    v: POST_SCHEMA_REVISION,
    kind,
    locale: postLocale(p),
    title: postTitle(p),
    excerpt: postExcerpt(p),
    cover: postCover(p),
    slides: slides.slice(0, POST_LIMITS.summarySlides),
    slide_count: slides.length,
    images: images.slice(0, 4),
    image_count: images.length,
    video_id: typeof p.videoId === 'string' && p.videoId ? p.videoId : null,
    link: p.link && httpsUrl(p.link.url, true) ? { url: p.link.url, title: p.link.title ?? null, description: p.link.description ?? null, image: p.link.image ?? null } : null,
    poll: p.poll ? { question: plainText(p.poll.question).slice(0, 300), options: opts(p.poll.options) } : null,
    quiz: p.quiz ? { question: plainText(p.quiz.question).slice(0, 300), options: opts(p.quiz.options) } : null,
    gif: p.gif ? asMedia(p.gif.url, null, p.gif.width, p.gif.height) : null,
    text: textBody ? textBody.slice(0, 1000) : null,
  };
}

/** Whether a post may have a www reference: published, public and not deleted (SS8: every such post does). */
export function isPublicPost(p: PostLike): boolean {
  return (p.status === 'published' || p.status === 'scheduled') && (p.visibility === undefined || p.visibility === 'public');
}

